package handlebars

import (
	"encoding/json"
	"os"
	"testing"
)

// Golden fixtures generated by testdata/gen/gen.js from handlebars.js 4.7.8.
// Regenerate: cd testdata/gen && npm ci && node gen.js > ../goldens.json
type goldenCase struct {
	Name        string            `json:"name"`
	Template    string            `json:"template"`
	Context     any               `json:"context"`
	Options     map[string]any    `json:"options"`
	Partials    map[string]string `json:"partials"`
	Helpers     map[string]string `json:"helpers"`
	Expected    string            `json:"expected"`
	ExpectError bool              `json:"expectError"`
	GenError    string            `json:"genError"`
}

type goldens struct {
	Generator string       `json:"generator"`
	Cases     []goldenCase `json:"cases"`
}

func TestGoldenDifferential(t *testing.T) {
	data, err := os.ReadFile("testdata/goldens.json")
	if err != nil {
		t.Skip("goldens not generated:", err)
	}
	var g goldens
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	t.Logf("generator: %s, %d cases", g.Generator, len(g.Cases))
	for _, c := range g.Cases {
		if c.GenError != "" {
			t.Errorf("%s: generator itself failed: %s", c.Name, c.GenError)
			continue
		}
		t.Run(c.Name, func(t *testing.T) {
			opts := &Options{}
			for k, v := range c.Options {
				switch k {
				case "strict":
					opts.Strict = v == true
				case "noEscape":
					opts.NoEscape = v == true
				case "compat":
					opts.Compat = v == true
				case "assumeObjects":
					opts.AssumeObjects = v == true
				case "preventIndent":
					opts.PreventIndent = v == true
				case "stringParams":
					opts.StringParams = v == true
				case "trackIds":
					opts.TrackIds = v == true
				case "knownHelpersOnly":
					opts.KnownHelpersOnly = v == true
				case "knownHelpers":
					if m, ok := v.(map[string]any); ok {
						opts.KnownHelpers = map[string]bool{}
						for name := range m {
							opts.KnownHelpers[name] = true
						}
					}
				}
			}
			if len(c.Helpers) > 0 {
				opts.Helpers = map[string]Helper{}
				for n, spec := range c.Helpers {
					if spec == "__param0__" {
						opts.Helpers[n] = func(call *HelperCall) (any, error) {
							if len(call.Params) == 0 {
								return nil, nil
							}
							return call.Params[0], nil
						}
					} else if spec == "__hash__" {
						opts.Helpers[n] = func(call *HelperCall) (any, error) {
							return stringify(call.Hash["first"]) + "-" + stringify(call.Hash["last"]), nil
						}
					} else if spec == "__block__" {
						opts.Helpers[n] = func(call *HelperCall) (any, error) {
							body, err := call.Fn(nil)
							if err != nil {
								return nil, err
							}
							return "B[" + body + "]", nil
						}
					} else {
						s := spec
						opts.Helpers[n] = func(call *HelperCall) (any, error) { return s, nil }
					}
				}
			}
			if len(c.Partials) > 0 {
				opts.Partials = map[string]*Template{}
				for n, src := range c.Partials {
					pt, err := Parse(src)
					if err != nil {
						t.Fatalf("partial %s: %v", n, err)
					}
					opts.Partials[n] = pt
				}
			}
			out, err := Render(c.Template, c.Context, opts)
			if c.ExpectError {
				if err == nil {
					t.Fatalf("want error, got %q", out)
				}
				return
			}
			if err != nil {
				t.Fatalf("error: %v", err)
			}
			if out != c.Expected {
				t.Fatalf("mismatch:\n got: %q\nwant: %q", out, c.Expected)
			}
		})
	}
}
